import {seedState, reduce, materialize, importState, today, addDays} from './model.js';
import {renderView} from './views.js';
import {h, icon, avatar} from './ui.js';

const KEY='familyhub-demo:data:v1';
const PROFILE_KEY='familyhub-demo:profile';
const app=document.getElementById('app');
const pages=[['overview','Überblick','home'],['calendar','Kalender','calendar'],['tasks','Aufgaben','check'],['rewards','Belohnungen','gift'],['shopping','Einkaufslisten','bag'],['fairness','Fairness','sparkles'],['family','Familie','users'],['kitchen','Küchenansicht','sun'],['settings','Demo & Einstellungen','settings']];
const roles={parent:'Elternansicht',child:'Kinderansicht',display:'Küchenanzeige'};
const difficulties={easy:'Leicht',medium:'Mittel',hard:'Knifflig'};
const recurrences={once:'Einmalig',daily:'Täglich',weekdays:'Montag bis Freitag',weekly:'Wöchentlich',monthly:'Monatlich',firstSaturday:'Erster Samstag im Monat',yearly:'Jährlich'};
let persistent=true,loadNotice='';
let state;
try{const stored=window.localStorage.getItem(KEY);state=stored?materialize(importState(stored)):seedState();}catch{state=seedState();loadNotice='Der gespeicherte Stand war nicht lesbar. Die Beispielfamilie wurde geladen.';}
let actorId='anna';try{actorId=window.sessionStorage.getItem(PROFILE_KEY)||actorId;}catch{}
const ui={page:pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'overview',taskFilter:'active',search:'',calendarMode:'month',calendarOffset:0,activeListId:state.shoppingLists[0]?.id||'',dialog:null,menu:false,tour:null};
function actor(){return state.members.find(m=>m.id===actorId)||state.members.find(m=>m.role==='parent')||state.members[0];}
if(actor().role==='display' && ui.page==='overview')ui.page='kitchen';
function persist(){try{window.localStorage.setItem(KEY,JSON.stringify(state));persistent=true;}catch{persistent=false;}}
persist();
export const getState=()=>structuredClone(state);

function toast(message,error=false){const region=document.getElementById('toasts');if(!region)return;const node=document.createElement('div');node.className='toast'+(error?' error':'');node.setAttribute('role',error?'alert':'status');node.innerHTML=icon(error?'info':'checkCircle');const text=document.createElement('span');text.textContent=message;node.append(text);region.append(node);window.setTimeout(()=>node.remove(),5000);}
function setProfile(id){if(!state.members.some(m=>m.id===id))return;actorId=id;try{window.sessionStorage.setItem(PROFILE_KEY,id);}catch{}ui.dialog=null;if(actor().role==='display')ui.page='kitchen';render();}
function navigate(page){if(!pages.some(p=>p[0]===page))return;ui.page=page;ui.menu=false;ui.dialog=null;history.pushState(null,'','#'+page);render();window.scrollTo?.({top:0,behavior:'smooth'});}
export function dispatch(action,payload={},message='Gespeichert.'){const next=reduce(state,actor().id,action,payload);state=materialize(next);persist();if(!state.shoppingLists.some(l=>l.id===ui.activeListId))ui.activeListId=state.shoppingLists[0]?.id||'';if(!state.members.some(m=>m.id===actorId))actorId=state.members.find(m=>m.role==='parent').id;ui.dialog=null;render();if(message)toast(persistent?message:message+' Speicherung ist hier deaktiviert; nutze den Export.');return getState();}
function closeDialog(){ui.dialog=null;render();}
function parentOnly(){if(actor().role!=='parent')throw Error('Wechsle oben zu einem Elternprofil, um das auszuprobieren.');}
const input=(name,label,value='',type='text',extra='')=>`<label class="field"><span>${h(label)}</span><input class="input" name="${h(name)}" type="${h(type)}" value="${h(value)}" ${extra}></label>`;
const textarea=(name,label,value='',extra='')=>`<label class="field span-two"><span>${h(label)}</span><textarea class="input" name="${h(name)}" rows="3" ${extra}>${h(value)}</textarea></label>`;
const select=(name,label,options,value)=>`<label class="field"><span>${h(label)}</span><select class="input" name="${h(name)}">${Object.entries(options).map(([key,text])=>`<option value="${h(key)}" ${key===String(value)?'selected':''}>${h(text)}</option>`).join('')}</select></label>`;
const note=text=>`<p class="form-note span-two">${h(text)}</p>`;
function dialog(title,kind,body,label='Speichern'){return `<dialog id="modal" class="modal" aria-labelledby="modal-title"><form class="modal-form" data-form="${h(kind)}"><header class="modal-heading"><div><p class="eyebrow">Euer Familienalltag</p><h2 id="modal-title">${h(title)}</h2></div><button type="button" class="icon-button" data-action="close-dialog" aria-label="Dialog schließen">${icon('close')}</button></header><div class="form-grid">${body}</div><p id="form-error" class="form-error" role="alert" hidden></p><footer class="modal-actions"><button type="button" class="button secondary" data-action="close-dialog">Abbrechen</button><button type="submit" class="button primary">${h(label)}</button></footer></form></dialog>`;}
function renderDialog(){const d=ui.dialog;if(!d)return '';const item=d.item||{};
 if(d.type==='task'){const series=state.taskSeries.find(s=>s.id===item.seriesId)||{};return dialog(item.id?'Aufgabe bearbeiten':'Eine neue Aufgabe','task',`${input('title','Was ist zu tun?',item.title||'','text','required maxlength="120" autocomplete="off"')}${input('points','Punkte',item.points??10,'number','required min="1" max="500"')}${textarea('description','Beschreibung',item.description||'','maxlength="1500" placeholder="Was ist dabei wichtig?"')}${select('difficulty','Schwierigkeit',difficulties,item.difficulty||'easy')}${input('dueDate','Erste Fälligkeit',series.dueDate||today(),'date','required')}${select('recurrence','Wiederholung',recurrences,series.recurrence||'once')}${note('Jede Wiederholung ist eine eigene Aufgabe. Änderungen gelten für offene Vorgänge; bestätigte Erfolge und Punkte bleiben erhalten.')}`,item.id?'Änderungen speichern':'Aufgabe anlegen');}
 if(d.type==='reward')return dialog(item.id?'Belohnung bearbeiten':'Eine neue Belohnung','reward',`${input('title','Belohnung',item.title||'','text','required maxlength="120"')}${input('cost','Benötigte Punkte',item.cost??30,'number','required min="1" max="10000"')}${select('category','Kategorie',{experience:'Erlebnis',money:'Taschengeld',screen:'Medienzeit',together:'Gemeinsame Zeit'},item.category||'experience')}${textarea('description','Darauf könnt ihr euch freuen',item.description||'','maxlength="1500"')}${note('Bereits angefragte Belohnungen behalten ihren ursprünglichen Punktepreis.')}`,item.id?'Speichern':'Belohnung anlegen');
 if(d.type==='event'){const people=state.members.filter(m=>m.role!=='display');return dialog(item.id?(item.recurrence!=='none'?'Terminserie bearbeiten':'Termin bearbeiten'):'Ein neuer Termin','event',`${input('title','Was habt ihr vor?',item.title||'','text','required maxlength="120"')}${input('date','Datum',item.date||d.date||today(),'date','required')}<label class="check-row span-two"><input type="checkbox" name="allDay" ${item.allDay?'checked':''}> Ganztägiger Termin</label>${input('start','Von',item.start||'16:00','time',item.allDay?'disabled':'required')}${input('end','Bis',item.end||'17:00','time',item.allDay?'disabled':'required')}${input('location','Ort',item.location||'','text','maxlength="120"')}${select('recurrence','Wiederholung',{none:'Einmalig',weekly:'Jede Woche',monthly:'Jeden Monat',yearly:'Jedes Jahr'},item.recurrence||'none')}${select('reminder','Erinnerung',{0:'Keine',5:'5 Minuten vorher',15:'15 Minuten vorher',30:'30 Minuten vorher',60:'1 Stunde vorher'},item.reminder??15)}<fieldset class="field span-two"><legend>Wer ist dabei?</legend><div class="member-checkboxes">${people.map(m=>`<label class="check-row">${avatar(m)}<input type="checkbox" name="members" value="${h(m.id)}" ${!item.id||(item.members||[]).includes(m.id)?'checked':''}>${h(m.name)}</label>`).join('')}</div></fieldset>${note('Termine und Erinnerungen sind Demodaten. Wiederkehrende Termine werden als ganze Serie bearbeitet; es werden keine echten Push-Mitteilungen versendet.')}`);}
 if(d.type==='member')return dialog(item.id?'Familienmitglied bearbeiten':'Platz für ein neues Mitglied','member',`${input('name','Name',item.name||'','text','required maxlength="60"')}${select('role','Perspektive',{parent:'Elternteil',child:'Kind',display:'Küchenanzeige'},item.role||'child')}${input('age','Alter',item.age??10,'number','required min="0" max="120"')}${input('color','Kalenderfarbe',item.color||'#8b5cf6','color')}${input('weeklyTarget','Persönliches Wochenziel in Aufgabenpunkten',item.weeklyTarget??40,'number','required min="0" max="10000"')}<fieldset class="field span-two"><legend>Passende Aufgabenstufen</legend><div class="member-checkboxes">${Object.entries(difficulties).map(([key,label])=>`<label class="check-row"><input type="checkbox" name="allowedDifficulties" value="${key}" ${(item.allowedDifficulties||['easy','medium']).includes(key)?'checked':''}>${label}</label>`).join('')}</div></fieldset>${note('Die Perspektiven simulieren Rollen innerhalb der Demo. Es wird kein echtes Benutzerkonto angelegt. Persönliche Ziele sind Orientierung und keine Rangliste.')}`);
 if(d.type==='adjust')return dialog('Punkte nachvollziehbar anpassen','adjust',`${select('memberId','Für wen?',Object.fromEntries(state.members.filter(m=>m.role==='child').map(m=>[m.id,m.name])),item.id||state.members.find(m=>m.role==='child')?.id)}${input('amount','Punkteänderung',10,'number','required min="-10000" max="10000"')}${textarea('reason','Begründung','','required maxlength="200" placeholder="Zum Beispiel: Gemeinsam beim Gartenprojekt geholfen"')}${note('Positive Zahlen schreiben Punkte gut, negative korrigieren sie. Jede Änderung erscheint im Journal; Guthaben kann nicht negativ werden.')}`,'Punkte buchen');
 if(d.type==='list')return dialog('Neue Einkaufsliste','list',input('name','Name der Liste','','text','required maxlength="80" placeholder="Zum Beispiel Drogerie"'),'Liste anlegen');
 if(d.type==='shopping-edit')return dialog('Einkaufsartikel bearbeiten','shopping-edit',`${input('name','Artikel',item.name,'text','required maxlength="120"')}${input('quantity','Menge',item.quantity,'text','maxlength="60"')}${input('category','Kategorie',item.category,'text','maxlength="60"')}`);
 if(d.type==='family')return dialog('Eure Familie, eure Regeln','family',`${input('name','Familienname',state.family.name,'text','required maxlength="80"')}${input('weeklyBonus','Wochenbonus in Punkten',state.family.weeklyBonus,'number','required min="1" max="1000"')}${note('Die Demo plant in Europe/Berlin. Der Wochenbonus belohnt mindestens eine bestätigte Aufgabe in jeder persönlich freigegebenen Schwierigkeitsstufe und ist einmal je Kind und Woche verfügbar.')}`);
 if(d.type==='simulation')return dialog('Einen Kalenderimport ausprobieren','simulation',`<div class="simulation-card span-two">${icon('calendar',36)}<h3>Beispieltermine statt Kontozugriff</h3><p>Wir fügen „Musikschule“ und „Familien-Spielenachmittag“ mit wiederkehrenden Beispieldaten hinzu. Die Daten bleiben in diesem Browser. Es wird kein Google- oder Nextcloud-Konto verbunden.</p></div>`,'Beispieltermine übernehmen');
 if(d.type==='confirm')return dialog(d.title,'confirm',`<p class="span-two confirm-copy">${h(d.text)}</p>`,d.label||'Bestätigen');
 return '';}

const tourSteps=[
 {page:'overview',role:'parent',title:'Ein Zuhause für euren Alltag',text:'Kalender, Aufgaben, Wünsche und Einkauf stehen gemeinsam im Überblick. Oben rechts kannst du jederzeit die Perspektive wechseln.'},
 {page:'tasks',role:'child',title:'Als Kind mithelfen',text:'Übernimm eine passende offene Aufgabe. Melde sie danach als fertig. Die Punkte kommen nach der Elternfreigabe.'},
 {page:'tasks',role:'parent',title:'Erfolge gemeinsam bestätigen',text:'Im Filter „Zur Freigabe“ kannst du eingereichte Aufgaben prüfen, freigeben oder zur Nachbesserung zurückgeben.'},
 {page:'rewards',role:'child',title:'Vorfreude sammeln',text:'Frage eine Belohnung an. Die Punkte werden reserviert, bis ein Elternteil den Wunsch bestätigt oder ablehnt.'},
 {page:'fairness',role:'parent',title:'Fair heißt: passend für jedes Kind',text:'Die Wochenziele orientieren sich an den freigegebenen Stufen. Verschiedene Beiträge können einmal pro Woche einen Bonus bringen.'},
 {page:'kitchen',role:'display',title:'Alles auf einem Blick',text:'Das Küchendisplay zeigt Termine, Aufgaben, Punkte und Einkauf. Im Menü „Demo & Einstellungen“ findest du Export und Neustart.'}
];
function applyTour(index){if(index>=tourSteps.length){ui.tour=null;toast('Viel Spaß beim weiteren Ausprobieren!');return render();}ui.tour=index;const step=tourSteps[index];const person=state.members.find(m=>m.role===step.role);if(person)actorId=person.id;ui.page=step.page;ui.taskFilter=step.role==='parent'&&index===2?'submitted':'active';render();}
function renderTour(){if(ui.tour===null)return '';const step=tourSteps[ui.tour];return `<aside class="tour-card" aria-labelledby="tour-title"><div class="tour-heading"><span class="badge">Rundgang · ${ui.tour+1}/${tourSteps.length}</span><button class="icon-button" data-action="tour-close" aria-label="Rundgang schließen">${icon('close')}</button></div><h2 id="tour-title">${h(step.title)}</h2><p>${h(step.text)}</p><div class="tour-actions"><button class="button ghost small" data-action="tour-close">Selbst ausprobieren</button><button class="button primary small" data-action="tour-next">${ui.tour===tourSteps.length-1?'Fertig':'Weiter'}${icon('arrow')}</button></div></aside>`;}

export function render(){const current=actor();const focus=document.activeElement;const focused=focus?.getAttribute('name');const caret=typeof focus?.selectionStart==='number'?focus.selectionStart:null;
 const pending=state.tasks.filter(t=>t.status==='submitted').length+state.redemptions.filter(r=>r.status==='pending').length;
 app.innerHTML=`<div class="demo-bar"><span class="demo-label">${icon('sparkles',15)} INTERAKTIVE DEMO</span><span class="demo-caption">Beispieldaten · ${persistent?'Änderungen bleiben in deinem Browser':'Speicherung hier nicht verfügbar'}</span><button type="button" data-action="start-tour">${icon('play',14)} Kurzer Rundgang</button></div><div class="app-shell ${ui.menu?'mobile-menu-open':''}"><aside class="sidebar" aria-label="Hauptnavigation"><a class="brand" href="#overview" data-action="nav" data-page="overview"><img src="./favicon.svg" width="39" height="39" alt=""><span>Family<span class="brand-light">Hub</span><small>Ein Zuhause für euren Alltag.</small></span></a><div class="family-label"><span></span>${h(state.family.name)}</div><nav class="nav-buttons">${pages.map(([id,name,symbol])=>`<button class="nav-link ${ui.page===id?'active':''}" data-action="nav" data-page="${id}" aria-current="${ui.page===id?'page':'false'}">${icon(symbol)}<span>${h(name)}</span>${id==='tasks'&&current.role==='parent'&&pending?`<span class="nav-count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-kindness">${icon('sun',29)}<p>Viele kleine Hände.<br><strong>Ein großes Miteinander.</strong></p></div><div class="profile-note">${avatar(current)}<div><strong>${h(current.name)}</strong><small>${roles[current.role]}</small></div></div></div></aside><div class="workspace"><header class="topbar"><button class="icon-button menu-button" data-action="toggle-menu" aria-label="Navigation öffnen" aria-expanded="${ui.menu}">${icon('menu')}</button><div class="breadcrumbs">FamilyHub <span>/</span> ${h(pages.find(p=>p[0]===ui.page)?.[1]||'Überblick')}</div><div class="topbar-actions"><div class="date-display">${icon('calendar',17)}<span>${new Intl.DateTimeFormat('de-DE',{weekday:'short',day:'numeric',month:'short',timeZone:state.family.timezone}).format(new Date())}</span></div>${current.role==='parent'?`<button class="icon-button notifications-button" data-action="notifications" aria-label="${pending} offene Freigaben">${icon('bell')}${pending?'<span class="notification-dot"></span>':''}</button>`:''}<label class="profile-switch">${avatar(current)}<span class="sr-only">Demo-Perspektive wechseln</span><select id="profile-select" aria-label="Demo-Perspektive wechseln">${state.members.map(m=>`<option value="${h(m.id)}" ${m.id===current.id?'selected':''}>${h(m.name)} · ${roles[m.role]}</option>`).join('')}</select></label></div></header><main id="main" class="main-content" tabindex="-1">${renderView({state,actor:current,ui,now:new Date()})}<footer class="app-footer"><span>FamilyHub · Gemeinsam wird Alltag leichter.</span><span>Eigenständige Demo ohne Nextcloud-Verbindung · <a href="https://github.com/ckshorty-sketch/FamilyHub-Demo" target="_blank" rel="noopener noreferrer">Quellcode</a></span></footer></main></div></div>${renderDialog()}${renderTour()}<input id="import-data" type="file" accept=".json,application/json" hidden>`;
 if(ui.dialog){const element=document.getElementById('modal');if(typeof element.showModal==='function')element.showModal();else element.setAttribute('open','');}
 syncMenuAccessibility();
 if(focused&&!ui.dialog){const element=[...app.querySelectorAll('input[name]')].find(n=>n.name===focused);if(element){element.focus();if(caret!==null&&element.setSelectionRange)try{element.setSelectionRange(caret,caret);}catch{}}}
}
function syncMenuAccessibility(){const sidebar=app.querySelector('.sidebar');if(sidebar)sidebar.inert=Boolean(window.matchMedia?.('(max-width: 720px)').matches&&!ui.menu);}
function open(type,item={},date){ui.dialog={type,item:structuredClone(item),date};render();}
function confirmAction(title,text,action,payload,label='Bestätigen'){ui.dialog={type:'confirm',title,text,action,payload,label};render();}
function showFormError(error){const target=document.getElementById('form-error');if(target){target.textContent=error.message;target.hidden=false;}else toast(error.message,true);}

document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const a=button.dataset.action;event.preventDefault();const id=button.dataset.id;
 try{
  switch(a){
   case 'nav':return navigate(button.dataset.page);
   case 'toggle-menu':ui.menu=!ui.menu;return render();
   case 'close-dialog':return closeDialog();
   case 'start-tour':return applyTour(0);
   case 'tour-next':return applyTour(ui.tour+1);
   case 'tour-close':ui.tour=null;return render();
   case 'notifications':navigate('tasks');ui.taskFilter='submitted';return render();
   case 'open-task':parentOnly();return open('task',state.tasks.find(t=>t.id===id));
   case 'open-reward':parentOnly();return open('reward',state.rewards.find(r=>r.id===id));
   case 'open-event':parentOnly();return open('event',state.events.find(e=>e.id===id),button.dataset.date);
   case 'open-member':parentOnly();return open('member',state.members.find(m=>m.id===id));
   case 'open-family':parentOnly();return open('family');
   case 'open-adjust':parentOnly();return open('adjust',state.members.find(m=>m.id===id));
   case 'open-list':return open('list');
   case 'open-shopping-item':{if(actor().role==='display')throw Error('Die Küchenanzeige ist schreibgeschützt.');const list=state.shoppingLists.find(l=>l.id===button.dataset.list);const item=list?.items.find(i=>i.id===id);if(!item)throw Error('Dieser Artikel ist nicht mehr vorhanden.');return open('shopping-edit',{...item,listId:list.id});}
   case 'task-filter':ui.taskFilter=button.dataset.filter;return render();
   case 'task-action':return dispatch('task.'+button.dataset.op,{id},({claim:'Danke fürs Übernehmen!',submit:'Fertigmeldung eingereicht. Jetzt sind die Eltern dran.',approve:'Erledigung freigegeben und Punkte gutgeschrieben.',reject:'Zur Nachbesserung zurückgegeben.',release:'Aufgabe freigegeben.'})[button.dataset.op]);
   case 'series-pause':return dispatch('series.pause',{id},'Wiederholung aktualisiert.');
   case 'series-archive':return confirmAction('Aufgabenserie beenden?','Offene Vorgänge werden entfernt. Übernommene Aufgaben und eure Erfolge bleiben erhalten.','series.archive',{id},'Serie beenden');
   case 'reward-request':{const reward=state.rewards.find(r=>r.id===id);return confirmAction('Deinen Wunsch anfragen?',`„${reward.title}“ kostet ${reward.cost} Punkte. Sie werden bis zur Elternentscheidung reserviert.`,'reward.request',{id},'Belohnung anfragen');}
   case 'reward-archive':return confirmAction('Belohnung archivieren?','Bereits angefragte Wünsche und der Punkteverlauf bleiben bestehen.','reward.archive',{id},'Archivieren');
   case 'redemption-action':return dispatch('redemption.'+button.dataset.op,{id},button.dataset.op==='approve'?'Wunsch freigegeben. Viel Freude damit!':'Anfrage abgelehnt und Punkte zurückgebucht.');
   case 'bonus-claim':return dispatch('bonus.claim',{memberId:id},'Wochenbonus gutgeschrieben. Jeder Beitrag zählt!');
   case 'event-delete':return confirmAction('Termin löschen?','Bei wiederkehrenden Terminen wird die gesamte Terminserie aus dieser Demo entfernt.','event.delete',{id},'Termin löschen');
   case 'calendar-nav':ui.calendarOffset=button.dataset.step==='0'?0:Math.max(-120,Math.min(120,ui.calendarOffset+Number(button.dataset.step)));return render();
   case 'calendar-mode':ui.calendarMode=button.dataset.mode;ui.calendarOffset=0;return render();
   case 'simulated-import':parentOnly();return open('simulation');
   case 'select-list':ui.activeListId=id;return render();
   case 'delete-list':return confirmAction('Einkaufsliste entfernen?','Die Liste und alle ihre Artikel werden aus deinem Browser-Datenstand entfernt.','shopping.list.delete',{id},'Liste entfernen');
   case 'shopping-toggle':return dispatch('shopping.item.toggle',{listId:button.dataset.list,id},'Einkaufsliste aktualisiert.');
   case 'shopping-delete':return dispatch('shopping.item.delete',{listId:button.dataset.list,id},'Artikel entfernt.');
   case 'remove-member':return confirmAction('Profil entfernen?','Profile mit Aufgaben- oder Punktehistorie bleiben zum Schutz des Verlaufs erhalten. Unbenutzte Profile können entfernt werden.','member.remove',{id},'Profil entfernen');
   case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`FamilyHub-Demo-${today()}.json`;link.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('Demodaten als JSON-Datei exportiert.');}
   case 'import':parentOnly();return document.getElementById('import-data').click();
   case 'reset':return confirmAction('Mit der Beispielfamilie neu starten?','Dies ersetzt nur deinen lokalen Demo-Datenstand in diesem Browser. Exportiere ihn vorher, wenn du ihn behalten möchtest.','reset',{},'Demo zurücksetzen');
   case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Nutze den Vollbildmodus deines Browsers für die Küchenansicht.');return;
  }
 }catch(error){toast(error.message||'Das hat gerade nicht geklappt.',true);}
});

document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('form[data-form]'))return;event.preventDefault();const kind=form.dataset.form;const data=new FormData(form);const value=name=>String(data.get(name)||'').trim();const number=name=>Number(value(name));const item=ui.dialog?.item;
 try{
  if(kind==='task')return dispatch(item?.id?'task.edit':'task.create',{...(item?.id?{id:item.id}:{}),title:value('title'),description:value('description'),points:number('points'),difficulty:value('difficulty'),recurrence:value('recurrence'),dueDate:value('dueDate')},'Aufgabe gespeichert.');
  if(kind==='reward')return dispatch(item?.id?'reward.edit':'reward.create',{...(item?.id?{id:item.id}:{}),title:value('title'),cost:number('cost'),category:value('category'),description:value('description')},'Belohnung gespeichert.');
  if(kind==='event')return dispatch(item?.id?'event.edit':'event.create',{...(item?.id?{id:item.id}:{}),title:value('title'),date:value('date'),start:value('start')||'00:00',end:value('end')||'23:59',allDay:data.has('allDay'),members:data.getAll('members').map(String),recurrence:value('recurrence'),location:value('location'),reminder:number('reminder')},'Termin gespeichert.');
  if(kind==='member')return dispatch(item?.id?'member.edit':'member.add',{...(item?.id?{id:item.id}:{}),name:value('name'),role:value('role'),color:value('color'),age:number('age'),weeklyTarget:number('weeklyTarget'),allowedDifficulties:value('role')==='display'?[]:data.getAll('allowedDifficulties').map(String)},'Familienprofil gespeichert.');
  if(kind==='adjust')return dispatch('points.adjust',{memberId:value('memberId'),amount:number('amount'),reason:value('reason')},'Punktekorrektur im Journal gebucht.');
  if(kind==='family')return dispatch('family.edit',{name:value('name'),timezone:'Europe/Berlin',weeklyBonus:number('weeklyBonus')},'Familieneinstellungen gespeichert.');
  if(kind==='list')return dispatch('shopping.list.create',{name:value('name')},'Einkaufsliste angelegt.');
  if(kind==='shopping-item'){const listId=value('listId');dispatch('shopping.item.add',{listId,name:value('name'),quantity:value('quantity'),category:value('category')},'Zur Einkaufsliste hinzugefügt.');return;}
  if(kind==='shopping-edit')return dispatch('shopping.item.edit',{listId:item.listId,id:item.id,name:value('name'),quantity:value('quantity'),category:value('category')},'Einkaufsartikel gespeichert.');
  if(kind==='simulation'){parentOnly();const examples=[{title:'Musikschule · Demo-Import',date:addDays(today(),2),start:'16:00',end:'17:00',members:state.members.filter(m=>m.role==='child').slice(0,1).map(m=>m.id),recurrence:'weekly',location:'Musikschule',allDay:false,reminder:15},{title:'Familien-Spielenachmittag · Demo-Import',date:addDays(today(),4),start:'15:00',end:'17:00',members:state.members.filter(m=>m.role!=='display').map(m=>m.id),recurrence:'weekly',location:'Zuhause',allDay:false,reminder:30}];let added=0;for(const example of examples)if(!state.events.some(e=>e.title===example.title)){state=reduce(state,actor().id,'event.create',example);added++;}persist();ui.dialog=null;navigate('calendar');return toast(added?`${added} fiktive Beispieltermine importiert.`:'Die Beispieltermine sind bereits vorhanden.');}
  if(kind==='confirm'){const d=ui.dialog;if(!d)return;if(d.action==='reset'){state=seedState();actorId=state.members.find(m=>m.role==='parent').id;ui.activeListId=state.shoppingLists[0]?.id;ui.tour=null;persist();navigate('overview');return toast('Die Beispielfamilie ist wieder startklar.');}return dispatch(d.action,d.payload,({ 'reward.request':'Wunsch angefragt. Die Punkte sind reserviert.','series.archive':'Serie beendet; übernommene Vorgänge bleiben bearbeitbar.'})[d.action]||'Änderung gespeichert.');}
 }catch(error){showFormError(error);}
});
document.addEventListener('input',event=>{if(event.target.dataset.action==='search'){ui.search=event.target.value;render();}});
document.addEventListener('change',async event=>{if(event.target.id==='profile-select')return setProfile(event.target.value);if(event.target.name==='allDay'){const form=event.target.closest('form');for(const name of ['start','end'])form.elements[name].disabled=event.target.checked;}
 if(event.target.id==='import-data'){const file=event.target.files?.[0];if(!file)return;try{parentOnly();if(file.size>1024*1024)throw Error('Bitte eine JSON-Datei mit höchstens 1 MB wählen.');const imported=materialize(importState(await file.text()));ui.dialog={type:'confirm',title:'Demo-Datei übernehmen?',text:'Der lokale Stand wird durch die geprüfte Datei ersetzt. Die Daten werden nirgendwo hochgeladen.',action:'import-state',payload:imported,label:'Daten übernehmen'};render();}catch(error){toast(error.message,true);}}
});
// File import is intentionally separate from domain actions: the file has
// already passed the strict model validator and is only stored locally.
document.addEventListener('submit',event=>{if(!event.target.matches('form[data-form="confirm"]')||ui.dialog?.action!=='import-state')return;event.preventDefault();event.stopImmediatePropagation();state=ui.dialog.payload;ui.dialog=null;actorId=state.members.find(m=>m.role==='parent').id;ui.activeListId=state.shoppingLists[0]?.id;persist();navigate('overview');toast('Geprüfte Demodaten übernommen.');},true);
document.addEventListener('cancel',event=>{if(event.target.id==='modal'){event.preventDefault();closeDialog();}},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&ui.menu){ui.menu=false;render();app.querySelector('.menu-button')?.focus();}});
document.addEventListener('click',event=>{if(ui.menu&&window.matchMedia?.('(max-width: 720px)').matches&&!event.target.closest('.sidebar, .menu-button')){ui.menu=false;render();}});
window.addEventListener('resize',syncMenuAccessibility);
window.addEventListener('popstate',()=>{const page=location.hash.slice(1);if(pages.some(p=>p[0]===page)){ui.page=page;ui.dialog=null;render();}});
window.addEventListener('storage',event=>{if(event.key!==KEY||!event.newValue)return;try{state=materialize(importState(event.newValue));if(!ui.dialog){render();toast('Änderungen aus einem anderen Tab übernommen.');}}catch{toast('Ein anderer Tab hat einen ungültigen Stand gespeichert. Dein Stand bleibt erhalten.',true);}});
window.setInterval(()=>{const clock=document.querySelector('[data-kitchen-clock]');if(clock)clock.textContent=new Intl.DateTimeFormat('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:state.family.timezone}).format(new Date());},15000);
render();
if(loadNotice)toast(loadNotice,true);
